        total_items_count = 0
        for cat_info in categories:
            category, created = Category.objects.update_or_create(
                name=cat_info["name"],
                defaults={
                    "icon": cat_info["icon"],
                    "description": cat_info["description"],
                    "sort_order": cat_info["sort_order"],
                    "is_active": True
                }
            )
            action = "Created" if created else "Updated"
            self.stdout.write(f"\n{action} Category: {category.name} ({category.icon})")

            for item_info in cat_info["items"]:
                menu_item, item_created = MenuItem.objects.update_or_create(
                    category=category,
                    name=item_info["name"],
                    defaults={
                        "description": item_info["description"],
                        "price": Decimal(str(item_info["price"])),
                        "image": item_info.get("image", ""),
                        "is_available": True,
                        "is_popular": item_info.get("is_popular", False),
                        "is_new": item_info.get("is_new", False),
                        "preparation_time": item_info.get("preparation_time", 20),
                        "dietary_tags": item_info.get("dietary_tags", []),
                        "icon_name": item_info.get("icon_name", "SparklesIcon"),
                        "sort_order": 0
                    }
                )
                total_items_count += 1
                i_action = "+" if item_created else "~"
                self.stdout.write(f"  {i_action} {menu_item.name} - ₦{menu_item.price:,.2f}")

        self.stdout.write(self.style.SUCCESS(f"\nSuccessfully seeded {len(categories)} categories, {total_items_count} items, and {len(tables_data)} dining tables!"))
